def pathset(pattern)
  group_texts = pattern.scan(/\(([^)]+)\)/).map(&:first)

  groups = group_texts.map do |text|
    text.split('|').map do |part|
      key, value = part.include?(':') ? part.split(':', 2) : [part, part]
      [key.to_s.strip.downcase.to_sym, value]
    end
  end

  raw = {}

  groups[0].product(*groups[1..]) do |values|
    path = pattern.dup

    group_texts.zip(values).each do |group_text, (_key, value)|
      path.sub!("(#{group_text})", value)
    end

    key = values.map { |k, _| k }.sort
    raw[key] = path
  end

  class << raw
    def [](*keys) = super(normalize(keys)) || raise(KeyError, "key not found: #{keys.inspect}")
    def fetch(*keys, &block) = super(normalize(keys), &block) || raise(KeyError, "key not found: #{keys.inspect}")
    def normalize(keys) = keys.flatten.map { |k| k.to_s.strip.downcase.to_sym }.sort
  end

  raw
end

def build_check(rebuild, pattern: :cpp, srcdir:, dst:)
  ptn = "".latest_file_pattern(pattern)
  latest_src = srcdir.latest_file(ptn) || ""

  loc = caller_locations(1..2).find { |l| l.path != __FILE__ }

  if (rebuild == "build" ) && dst.mtime > latest_src.mtime
    puts "(#{loc.path}:#{loc.lineno})build skip " +  "#{File.basename(dst)}:#{dst.mtime.strftime("%F %T")} > #{File.basename(latest_src)}:#{latest_src.mtime.strftime("%F %T")} latest in #{srcdir}/#{ptn}"
    exit(0)
  else
    puts "(#{loc.path}:#{loc.lineno})build" + " #{File.basename(dst)}:#{dst.mtime.strftime("%F %T")} <= #{File.basename(latest_src)}:#{latest_src.mtime.strftime("%F %T")} latest in #{srcdir}/#{ptn}"
  end
end

def release(src:, dst:)
  src.sync(dst)
end

# String　を Riafile のタスク用にいろいろと拡張して、見通しよくする
class String
  def fullpath
    # caller_locations で呼び出し元のスタックを取得
    # [1] だと String#fullpath 自身を指すことがあるため、1つ外側を指定
    loc = caller_locations(1..2).find { |l| l.path != __FILE__ }
    raise "caller_locations loc emply" unless loc # 万が一取得できなかった場合の安全弁

    # loc.path はファイル名まで含むので、File.dirname でディレクトリパスにする
    # 絶対パス化して、スラッシュをバックスラッシュに置換
    File.expand_path(self, File.dirname(loc.path)).tr("/", "\\")
  end
  def mkdir
    require 'fileutils'
    FileUtils.mkdir_p(File.dirname(self))
    self
  end
  def del
    if !self.empty?
      if File.file?(self)
        pp self
        File.delete(self)
      end
      if File.directory?(self)
        Kernel.require 'fileutils'
        FileUtils.rm_rf(self)
      end
    end
    self
  end

  def exec(*args, **kwargs)
    fullpath = File.expand_path(self).tr("/", "\\")
    abort "#{File.basename(fullpath)} ないです #{fullpath}" if not File.exist?(fullpath)
    sh(fullpath, *args, **kwargs)
  end

  def dirname = File.dirname(self)
  def basename(*args) = File.basename(self, *args)
  def extname = File.extname(self)

  def cp_r(dest)
    require "pathname"
    me = Pathname.new(File.expand_path(self))
    Dir.glob(File.expand_path("**/*", self), File::FNM_DOTMATCH).each do |fn|
      if File.file?(fn)
        Pathname.new(fn).relative_path_from(me).tap do |rel|
          dst = File.join(dest, rel)
          fn.cp(dst.mkdir)
        end
      end
    end
  end

  def cp_from(src)
    src.cp(self)
    self
  end

  def cp(dest)
    require 'fileutils'

    fullpath = File.expand_path(self).ospath
    dest_fullpath = File.expand_path(dest).ospath

    abort "#{File.basename(fullpath)} ないです #{fullpath}" if not File.exist?(fullpath)

    # dest が既存ディレクトリなら、その中の同名ファイルをコピー先とみなす
    actual_dest =
      if File.directory?(dest_fullpath)
        File.join(dest_fullpath, File.basename(fullpath))
      else
        dest_fullpath
      end

    if File.exist?(actual_dest) && File.mtime(actual_dest) >= File.mtime(fullpath)
      puts "skip #{fullpath} -> #{actual_dest}"
      return actual_dest
    end

    FileUtils.mkdir_p(File.dirname(actual_dest))
    FileUtils.cp(fullpath, actual_dest)
    puts "cp #{fullpath} -> #{actual_dest}"

    self
  end

  def symlink(dest)
    dst = File.expand_path(dest)
    File.delete(dst) if File.exist?(dst)
    File.symlink(File.expand_path(self), dst)
  end

  def latest_file_pattern(pattern)
    return case pattern
      in :cs
        "**/*.{cs,xaml,xcss,csproj,slnx,sln}"
      in :cpp | :c
        "**/*.{c,cpp,h,rc,vcxproj,slnx,sln,hpp}"
      in String => custom
        custom
      else
        raise ArgumentError, "不正な引数です: #{pattern}"
    end
  end

  def latest_file(pattern = :cpp)
    ptn = latest_file_pattern(pattern)

    ret = Dir.glob(File.join(self, ptn).tr("\\", "/"))
       .select { |f| File.file?(f) }
       .map    { |f| { mtime: File.mtime(f), file: f } }
       .max_by { |h| h[:mtime] }
       &.[](:file)
    return ret
  end

  def mtime
    return Time.at(0) unless self && File.file?(self)
    return File.mtime(self)
  end

  def s(*args)
    pathset(self).fetch(*args)
  end

  def readonly
    mode = File.stat(self).mode
    File.chmod(mode & ~0o222, self) # user/group/other の書込権限を除去
    self
  end

  def sync(dest)
    require "pathname"
    require "fileutils"

    src = Pathname.new(File.expand_path(self))
    dst = Pathname.new(File.expand_path(dest))

    puts "sync: #{src} -> #{dst}"

    # dest にしかないファイルを削除
    Dir.glob(dst.join("**/*")).each do |fn|
      next unless File.file?(fn)

      rel = Pathname.new(fn).relative_path_from(dst)

      unless src.join(rel).file?
        puts "  delete: #{rel}"
        FileUtils.rm_f(fn)
      end
    end

    # src -> dest
    Dir.glob(src.join("**/*")).each do |fn|
      next unless File.file?(fn)

      rel = Pathname.new(fn).relative_path_from(src)
      out = dst.join(rel)

      puts "  copy:   #{rel}"
      FileUtils.mkdir_p(out.dirname)
      FileUtils.cp(fn, out)
    end

    # 空ディレクトリを削除
    Dir.glob(dst.join("**/*"))
      .select { |fn| File.directory?(fn) }
      .sort_by(&:length)
      .reverse_each do |fn|
        if Dir.empty?(fn)
          rel = Pathname.new(fn).relative_path_from(dst)
          puts "  rmdir:  #{rel}"
          Dir.rmdir(fn)
        end
      end

    puts "sync: done"
  end

  def ospath
    return tr("/", "\\") if windows?

    path = tr("\\", "/")
    ENV["WSL_DISTRO_NAME"] ? path.sub(/\A([a-z]):\//i) { "/mnt/#{Regexp.last_match(1).downcase}/" } : path
  end

  def exename
    windows? ? sub(/\.exe\z/i, "") + ".exe" : sub(/\.exe\z/i, "")
  end

  def install?(apt: nil, &block)
    found = windows? ? system("where", self, out: File::NULL, err: File::NULL) : system("bash", "-lc", "command -v #{Shellwords.escape(self)} >/dev/null 2>&1")
    return true if found

    ($install_queue ||= { apt: [], blocks: [] })[:apt] << apt if apt
    ($install_queue ||= { apt: [], blocks: [] })[:blocks] << block if block
    false
  end
  def gen(s)
    fn = self
    self.mkdir

    if File.exist?(fn) && File.binread(fn) == s
      Kernel.puts "skip: #{fn}"
      return false
    end

    File.binwrite(fn, s)
    Kernel.puts "generate: #{fn}"
    self
  end
  def append(text)
    path = File.expand_path(self)
    File.open(path, "a") do |f|
      f.puts(text)
    end
  end
end

# 使い方
# "a.exe".build?("src/**/*", rebuild: rebuild) do
#   sh "build"
# end
class String
  def build?(*inputs, rebuild:nil, verbose:false, &block)
    raise ArgumentError, "build? requires a block" unless block_given?

    dst = File.expand_path(self)
    files = inputs.flat_map { Dir.glob(_1) }.select { File.file?(_1) }

    latest = files.max_by { File.mtime(_1) }
    latest_time = latest ? File.mtime(latest) : Time.at(0)
    dst_exists = File.exist?(dst)
    dst_time = dst_exists ? File.mtime(dst) : nil

    rebuild_requested = rebuild == true || rebuild == "rebuild"
    missing = !dst_exists
    outdated = dst_exists && latest_time > dst_time

    build =
      rebuild_requested ||
      missing ||
      outdated

    if verbose
      puts "build? #{self}"
      puts "  self:    #{self}"
      puts "  dst:     #{dst}"
      puts "  rebuild: #{rebuild.inspect}"
      puts "  exists:  #{dst_exists}"
      puts "  dst mtime:    #{dst_time || '-'}"
      puts "  latest input: #{latest || '-'}"
      puts "  input mtime:  #{latest ? latest_time : '-'}"
      puts "  inputs:       #{files.size}"

      reason =
        if rebuild_requested
          "rebuild requested"
        elsif missing
          "destination missing"
        elsif outdated
          "input newer than destination"
        else
          "up-to-date"
        end

      puts "  => #{build ? 'BUILD' : 'SKIP'} (#{reason})"
    end

    if build
      params = block.parameters

      # 引数の渡し方を動的に切り替える
      case params.size
      when 0
        # ブロックが引数を何も受け取らない場合: instance_exec や 引数なしで実行
        block.call
      when 1
        # ブロックが 1 つだけ引数を受け取る場合 (|dst:| または |dst|)
        # キーワード引数か位置引数かを判定
        if params.first.first == :keyreq || params.first.first == :key
          block.call(dst: self)
        else
          block.call(self)
        end
      else
        # ブロックが 2 つ以上の引数を受け取る場合 (|dst:, src:| や |dst, src|)
        # キーワード引数の場合
        if params.any? { |type, _| type == :keyreq || type == :key }
          block.call(dst: self, src: files)
        else
          # 位置引数の場合
          block.call(self, files)
        end
      end
    end

    return self
  end
end

class Command
  attr_reader :name, :cwd, :env, :command, :block, :comment, :file, :line, :opt_specs

  def initialize(name, cwd, env, command, block, comment, file, line)
    @name = name
    @cwd = cwd || "."
    @env = env.dup
    @command = command
    @block = block
    @comment = comment
    @file = file
    @line = line
    @opt_specs = []
  end

  def run(args)
    @env.each do |k, v|
      ENV[k] ||= v
    end

    $install_queue = { apt: [], blocks: [] }
    Dir.chdir(@cwd) do
      if @block
        run_block(args)
      else
        sh(@command, *args, file:@file, line:@line)
      end
    end
    run_install_queue(file: @file, line: @line)
  end

  def set_opt_specs(specs)
    @opt_specs = specs.dup
  end

  def list_text
    if comment
      comment
    else
      command || ""
    end
  end

  def opt_text
    return "" if @opt_specs.empty?

    " " + @opt_specs.map(&:raw).join(" ")
  end

  def location
    "#{File.basename(file)}:#{line}"
  end

  def describe
    { "name" => name, "file" => File.expand_path(file), "line" => line,
      "opt" => @opt_specs.map(&:raw).join(" "), "help" => list_text }
  end

  private

  def run_block(args)
    if block_keyword_names.empty?
      validate_positional_args!(args)
      @block.call(*args)
      return
    end

    kwargs, rest = consume_opt_args(args)
    validate_positional_args!(rest)
    kwargs = kwargs.transform_keys(&:to_sym)
    @block.call(*rest, **kwargs)
  end

  def validate_positional_args!(args)
    params = @block.parameters
    expected = params.count { |kind, _| [:req, :opt].include?(kind) }
    has_rest = params.any? { |kind, _| kind == :rest }
    raise ArgumentError, "missing argument(s) for #{name}: expected #{expected}, got #{args.length}" if args.length < expected
    raise ArgumentError, "too many arguments for #{name}: expected at most #{expected}, got #{args.length}" if !has_rest && args.length > expected
  end

  def block_keyword_names
    return [] unless @block

    @block.parameters
      .select { |kind, _name| [:keyreq, :key].include?(kind) }
      .map { |_, param_name| param_name.to_s }
  end

  def block_required_keyword_names
    return [] unless @block

    @block.parameters
      .select { |kind, _name| kind == :keyreq }
      .map { |_, param_name| param_name.to_s }
  end

  def opt_option_name(spec)
    spec.raw[1...-1].split("=", 2).first
  end

  def opt_arg_matches_spec?(arg, spec)
    case spec.kind
    when :flag
      spec.key == arg
    when :select
      spec.choices.include?(arg)
    when :string
      arg.include?("=") && arg.split("=", 2).first == spec.key
    else
      false
    end
  end

  def consume_opt_args(args)
    params = @opt_specs.to_h { |spec| [spec.key, spec.default] }
    consumed_keys = {}
    rest = []

    i = 0
    while i < args.length
      arg = args[i]
      matched = false

      @opt_specs.each do |spec|
        next if consumed_keys[spec.key]

        value = if spec.kind == :flag && spec.key == arg
          arg
        elsif spec.kind == :select && spec.choices.include?(arg)
          arg
        elsif spec.kind == :string
          option = opt_option_name(spec)
          if arg.start_with?("#{option}=")
            arg.split("=", 2)[1]
          elsif arg == option
            raise ArgumentError, "missing value for #{name}: #{option}" if i + 1 >= args.length
            i += 1
            args[i]
          end
        end
        next if value.nil?

        raise ArgumentError, "option duplicated for #{name}: #{spec.raw}" if consumed_keys[spec.key]
        params[spec.key] = value
        consumed_keys[spec.key] = true
        matched = true
        break
      end

      rest << arg unless matched
      i += 1
    end
    missing = block_required_keyword_names.reject { |key| params.key?(key) }
    raise ArgumentError, "missing parameter(s) for #{name}: #{missing.join(', ')}" unless missing.empty?
    [params, rest]
  end
end

# 実行は子の ria へ渡す。表示情報だけ --json で取得し、元の定義を同じプロセスで eval しない。
class DelegatedCommand < Command
  def initialize(name, cwd, env, file, line)
    super(name, cwd, env, nil, nil, nil, file, line)
    @source_dir = File.expand_path(@cwd)
  end

  def run(args)
    require "rbconfig"
    @env.each { |key, value| ENV[key] ||= value }
    sh RbConfig.ruby, "--disable-gems", File.expand_path(__FILE__), name, *args,
       pwd: @source_dir, file: file, line: line, no_cmd_c: true
  end

  def self.command_info(dir, env)
    require "json"
    require "open3"
    require "rbconfig"
    # 同じ一覧表示中だけ共有。別の ria 起動では必ず読み直す。永続キャッシュは持たない。
    @sources ||= {}
    @sources[[dir, env]] ||= begin
      output, diagnostic, status = Open3.capture3(env, RbConfig.ruby, "--disable-gems",
        File.expand_path(__FILE__), "--json", chdir: dir)
      raise ArgumentError, "ria の定義情報を取得できません: #{dir}\n#{diagnostic.strip}" unless status.success?
      $stderr.write(diagnostic)
      entries = JSON.parse(output)
      unless entries.is_a?(Array) && entries.all? { |entry|
        entry.is_a?(Hash) && entry['name'].is_a?(String) && entry['file'].is_a?(String) &&
          entry['line'].is_a?(Integer) && entry['opt'].is_a?(String) && entry['help'].is_a?(String)
      }
        raise ArgumentError, "ria の定義情報が不正です: #{dir}"
      end
      entries.to_h { |entry| [entry.fetch('name'), entry] }
    rescue JSON::ParserError => error
      raise ArgumentError, "ria の定義情報を解釈できません: #{dir}: #{error.message}"
    end
  end

  def describe
    effective_env = @env.to_h { |key, value| [key, ENV[key] || value] }
    self.class.command_info(@source_dir, effective_env).fetch(name) do
      raise ArgumentError, "委譲先にコマンドがありません: #{@source_dir}: #{name}"
    end
  end

  def list_text
    describe.fetch('help')
  end

  def opt_text
    text = describe.fetch('opt')
    text.empty? ? "" : " #{text}"
  end

  def location
    info = describe
    "#{info.fetch('file')}:#{info.fetch('line')}"
  end
end

# cwd の先にある通常の Riafile のコマンドを公開する。採番はこの登録順だけで決まる。
def ria(name)
  loc = caller_locations(1, 1)[0]
  item = DelegatedCommand.new(name.to_s, $cwd, $env, loc.path, loc.lineno)
  $commands[item.name] = item
  $order << item
end

def cmd(name = nil, command = nil, **kwargs, &block)
  loc = caller_locations(1, 1)[0]
  comment = $source_lines[loc.lineno - 1]&.split("#", 2)&.[](1)&.strip
  local_opt_spec = kwargs.delete(:opt)

  if kwargs.any?
    kwargs.each do |key, value|
      if value.is_a?(Proc)
        add_cmd(key.to_s, nil, comment, value, loc.path, loc.lineno, local_opt_spec)
      else
        add_cmd(key.to_s, value, comment, nil, loc.path, loc.lineno, local_opt_spec)
      end
    end
    return
  end

  if block
    add_cmd(name.to_s, command, comment, block, loc.path, loc.lineno, local_opt_spec)
    return
  end

  if command.nil?
    add_cmd(name.to_s, name.to_s, comment, nil, loc.path, loc.lineno)
    return
  end

  add_cmd(name.to_s, command, comment, nil, loc.path, loc.lineno, local_opt_spec)
end

def add_cmd(name, command, comment, block, file, line, local_opt_spec = nil)
  item = Command.new(name, $cwd, $env, command, block, comment, file, line)
  item.set_opt_specs(resolve_cmd_opt_specs(name, block, local_opt_spec, file, line)) if block

  $commands[name] = item
  $order << item
end

