$env = {}
def env(hash, &block)
  raise "env does not take a block" if block

  $env.merge!(hash.transform_keys(&:to_s))
end

OptSpec = Struct.new(:kind, :key, :default, :choices, :raw, keyword_init: true)

def parse_opt_spec(spec)
  spec.to_s.scan(/\[[^\]]+\]/).map do |token|
    parse_opt_token(token)
  end
end

def parse_opt_token(token)
  inner = token[1..-2]

  if inner.include?("|")
    parts = inner.split("|")
    star_count = parts.count { |part| part.start_with?("*") }

    raise "selective opt allows at most one default: #{token}" if star_count > 1

    choices = parts.map { |part| part.sub(/\A\*/, "") }
    default_part = parts.find { |part| part.start_with?("*") }

    return OptSpec.new(
      kind: :select,
      key: default_part&.sub(/\A\*/, "") || choices.first,
      default: default_part&.sub(/\A\*/, ""),
      choices: choices,
      raw: token
    )
  end

  if inner.include?("=")
    option, default = inner.split("=", 2)
    raise "string opt key missing: #{token}" if option.empty?
    key = option.sub(/\A--/, "").tr("-", "_")

    return OptSpec.new(
      kind: :string,
      key: key,
      default: default,
      choices: nil,
      raw: token
    )
  end

  if inner =~ /\A[A-Za-z_][A-Za-z0-9_-]*\z/
    return OptSpec.new(
      kind: :flag,
      key: inner,
      default: nil,
      choices: nil,
      raw: token
    )
  end

  raise "invalid opt token: #{token}"
end

def opt_input_tokens_for(spec)
  if spec.kind == :select
    spec.choices
  elsif spec.kind == :string
    [spec.raw[1...-1].split("=", 2).first]
  else
    [spec.key]
  end
end

def merge_opt_specs(specs, source)
  merged = {}
  input_tokens = {}

  specs.each do |spec|
    raise "#{source} opt parameter duplicated: #{spec.key}" if merged.key?(spec.key)

    opt_input_tokens_for(spec).each do |token|
      if input_tokens.key?(token)
        raise "#{source} opt token duplicated: #{token} (#{spec.raw} vs #{input_tokens[token]})"
      end
    end

    merged[spec.key] = spec
    opt_input_tokens_for(spec).each do |token|
      input_tokens[token] = spec.raw
    end
  end

  merged
end

def opt_spec_accepts_keyword?(spec, keyword)
  spec.key == keyword || (spec.kind == :select && spec.choices.include?(keyword))
end

def resolve_cmd_opt_specs(name, block, local_opt_spec = nil, file = nil, line = nil)
  params = block.parameters
  keyword_names = params
    .select { |kind, _param_name| [:keyreq, :key].include?(kind) }
    .map { |_, param_name| param_name.to_s }

  source = "#{file}:#{line}: cmd #{name}"
  specs = merge_opt_specs(parse_opt_spec(local_opt_spec), source).values

  if keyword_names.empty?
    raise SyntaxError, "#{source}: opt argument(s) not received: #{specs.map(&:raw).join(' ')} (declare a matching keyword parameter, e.g. a:)" unless specs.empty?
    return []
  end
  resolved = []
  used_spec_ids = {}
  missing = []

  keyword_names.each do |param_name|
    matches = specs.select { |item| opt_spec_accepts_keyword?(item, param_name) }

    if matches.empty?
      missing << param_name
      next
    end

    if matches.size > 1
      raise "#{source} opt parameter ambiguous: #{param_name} (#{matches.map(&:raw).join(' vs ')})"
    end

    spec = matches.first

    if used_spec_ids.key?(spec.object_id)
      prev = used_spec_ids[spec.object_id]
      raise "#{source} opt group duplicated in block parameters: #{prev}, #{param_name} (#{spec.raw})"
    end

    used_spec_ids[spec.object_id] = param_name

    # [*debug|release] は debug: でも release: でも受けられる。
    # ただし同じ select group から block 引数にできるのは1つだけ。
    copy = spec.dup
    copy.key = param_name
    resolved << copy
  end

  raise SyntaxError, "#{source}: missing opt definition(s): #{missing.join(', ')} (add matching opt declarations)" unless missing.empty?

  unused = specs.reject { |spec| used_spec_ids.key?(spec.object_id) }
  unless unused.empty?
    raise SyntaxError, "#{source}: opt argument(s) not received: #{unused.map(&:raw).join(' ')} (declare a matching keyword parameter, e.g. a:)"
  end

  resolved
end

def cwd(dir, &block)
  raise "cwd nested error" if $cwd
  warn "#{caller_locations(1, 1)[0]}: `#{dir}` cwd dir missing." if not Dir.exist?(dir)

  old = $cwd
  $cwd = dir
  block.call
ensure
  $cwd = old
end

def print_cmd_list(items, title: nil, show_subcommand_parents: false)
  puts title if title
  items.each_with_index do |item, i|
    name =
      if item.name == item.command && !item.block
        " " * (5)
      else
        ("%-5s".colorize(:light_white) % [item.name])
      end

    text = item.list_text
    text = " #{text}".colorize(:green) unless text.empty?

    #loc = ("%s" % (File.expand_path(item.location).colorize(background: :magenta) + ":")) .colorize(:dark_gray)
    loc = ("%s" % (item.location.colorize(background: :magenta) + ":")) .colorize(:dark_gray)

    puts "%s ria %-2d: %s%s%s" % [loc, i + 1, name, item.opt_text, text]
  end

  return unless show_subcommand_parents

  command_names = items.map(&:name)
  parent_names = items.filter_map do |item|
    item.name.split("-", 2).first if item.name.include?("-")
  end.uniq

  parent_names.reject! { |name| command_names.include?(name) }
  parent_names.each { |name| puts "    ria #{name} : #{command_names.select { |cmd| cmd.start_with?("#{name}-") }.join(', ')}" }
end

def cut_cmd(s, max = 200)
  return s if s.length <= max

  s[0, max] + "...(#{s.length} chars)"
end

def windows?
  /mswin|mingw|cygwin/ === RUBY_PLATFORM
end

def riafile2cmd(riafile = "Riafile", name = nil)
  require "rbconfig"
  require "pathname"

  riafile = File.expand_path(riafile)
  raise ArgumentError, "Riafile not found: #{riafile}" unless File.file?(riafile)
  name ||= File.basename(File.dirname(riafile))
  raise ArgumentError, "invalid command name: #{name}" unless /\A[A-Za-z0-9_][A-Za-z0-9_.-]*\z/.match?(name)

  directory = if windows?
    profile = ENV.fetch("USERPROFILE") { raise ArgumentError, "USERPROFILE is not set" }
    path = File.join(profile, "AppData", "Local", "Microsoft", "WindowsApps")
    raise ArgumentError, "WindowsApps directory is not writable: #{path}" unless Pathname.new(path).absolute? && File.directory?(path) && File.writable?(path)
    path
  else
    require "fileutils"
    path = File.join(Dir.home, ".local", "bin")
    FileUtils.mkdir_p(path)
    path
  end

  args = [RbConfig.ruby, "--disable-gems", File.realpath(__FILE__), "--riafile", riafile]
  header = windows? ? "@echo off\r\nrem Generated by ria --riafile2cmd\r\n" : "#!/bin/sh\n# Generated by ria --riafile2cmd\n"
  content = if windows?
    quoted = args.map { |arg| '"' + arg.gsub("%", "%%") + '"' }.join(" ")
    "#{header}setlocal DisableDelayedExpansion\r\n#{quoted} %*\r\nexit /b %errorlevel%\r\n"
  else
    "#{header}exec #{Shellwords.join(args)} \"$@\"\n"
  end
  target = File.join(directory, name + (windows? ? ".cmd" : ""))
  begin
    File.open(target, "wbx", 0o755) { |file| file.write(content) }
  rescue Errno::EEXIST
    unless !File.symlink?(target) && File.binread(target, header.bytesize) == header
      raise ArgumentError, "refusing to overwrite existing file without riafile2cmd header: #{target}"
    end
    require "tempfile"
    Tempfile.create([".#{name}-", ".tmp"], directory) do |file|
      file.binmode
      file.write(content)
      file.chmod(0o755)
      file.close
      File.rename(file.path, target)
    end
  end
  puts "installed: #{target}"
  unless windows? || ENV.fetch("PATH", "").split(File::PATH_SEPARATOR).include?(directory)
    warn 'Add to your shell startup file: export PATH="$HOME/.local/bin:$PATH"'
  end
  target
rescue SystemCallError => e
  raise ArgumentError, e.message
end

def run_install_queue(file:, line:)
  queue = $install_queue
  $install_queue = nil
  return unless queue

  unless queue[:apt].empty?
    sudo = !Process.euid.zero?
    raise ArgumentError, "install? apt requires sudo, but stdin has no TTY" if sudo && !$stdin.tty?

    prefix = sudo ? "sudo " : ""
    sh "#{prefix}apt-get update", file: file, line: line
    sh "#{prefix}apt-get install -y #{queue[:apt].uniq.map { |name| Shellwords.escape(name) }.join(' ')}", file: file, line: line
  end
  queue[:blocks].each(&:call)
end

def up(*cmd, exe: nil, port: nil, cold: nil, **opt)
  if port
    require "socket"
    begin
      TCPSocket.new("127.0.0.1", port).close
      return 0
    rescue Errno::ECONNREFUSED, Errno::ETIMEDOUT
    end
  else
    exe = File.basename(exe || cmd.first.to_s.split(/\s/, 2).first)
    return 0  if `tasklist /FI "IMAGENAME eq #{exe}" /NH`.each_line.any? { _1.match?(/\A#{Regexp.escape(exe)}\s/i) }
  end

  code = sh(*cmd, **opt)
  sleep cold if cold && code == 0
  code
end

def sh(*cmd, env: {}, file:nil, line:nil, abort: true, pwd:nil, no_cmd_c: !windows?)
  raise "env は hash で。" if not env.is_a?(Hash)
  ENV["RIA_CALL"] = "1"
  # コールスタックから $riafile と完全一致するパス（Riafile 内の行）を探す
  if file == nil
    ria_loc = caller_locations.find { |loc| loc.path == $riafile }
    file = ria_loc.path
    line = ria_loc&.lineno || 0
  end

  Dir.chdir(pwd || Dir.pwd) do
    short_cmd = cut_cmd(cmd.join(" "))
    envs = env.transform_keys(&:to_s).transform_values(&:to_s)
    unless ria_silence?
      puts "(#{file}:#{line}) #{Dir.pwd}"
      envs.each do |k, v|
        puts "> set #{k}=#{v}"
      end
      puts "> #{short_cmd}"
    end

    if !no_cmd_c
      if windows?
        system(envs, "cmd", "/c", *cmd)
      else
        system(envs, "bash", "-lc", *cmd.map(&:to_s))
      end
    else
      system(envs, *cmd)
    end

    code = $?.exitstatus

    if code != 0 && abort
      warn "(ria) abort: [#{short_cmd}] (exit:#{code || "unknown"})"
      exit(code || 1)
    end
    code
  end
end

def mutex(key:$riafile, dir: ENV["TMP"], &block)
  require "digest"
  name = Digest::SHA256.hexdigest(File.expand_path(key))
  path = File.join(dir, "mutex-#{name}.lock")

  File.open(path, File::RDWR | File::CREAT, 0o644) do |f|
    f.flock(File::LOCK_EX)
    begin
      block.call
    ensure
      f.flock(File::LOCK_UN)
    end
  end
end

def exitputs(s)
  puts s
  exit(1)
end

def cl(cmd, output: nil)
  args = cmd.split(" ")
  args << "/Fe:#{output}" if output

  # Developer Command Prompt 上、または cl に PATH が通っていれば直接実行
  if ENV['VCINSTALLDIR'] || system("where cl >NUL 2>&1")
    return sh "cl", *args
  end

  vswhere = "C:\\Program Files (x86)\\Microsoft Visual Studio\\Installer\\vswhere.exe"
  raise "Visual Studio / Build Tools が見つかりません" unless File.exist?(vswhere)

  vs_path = `"#{vswhere}" -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath`.strip
  vs_dev_cmd = File.join(vs_path, "Common7\\Tools\\VsDevCmd.bat")

  # 1行で vcvars/VsDevCmd を call してそのまま cl を実行する Proc を返す
  sh "cmd.exe", "/c",
     "call", vs_dev_cmd, "-arch=x64",
     "&&",
     "cl", *args,
     no_cmd_c: true
end

if __FILE__ == $0
  begin
    ENV["RIA_PWD"] ||= Dir.pwd
    riafile = File.join(Dir.pwd, "Riafile")
    json = false
    while ["--riafile", "--silence", "-s", "--json"].include?(ARGV.first)
      option = ARGV.shift
      if option == "--riafile"
        path = ARGV.shift
        raise ArgumentError, "--riafile requires a path" unless path
        riafile = File.expand_path(path)
      elsif option == "--json"
        json = true
        ENV["RIA_SILENCE"] = "1"
      else
        ENV["RIA_SILENCE"] = "1"
      end
    end
    key = ARGV.shift
    raise ArgumentError, "usage: ria [--riafile PATH] --json（一覧情報の取得のみ）" if json && key

  case key # 後続処理が不要ならここで終わり
  when "--help", "-h"
    puts "ria [--riafile PATH] [--help|-h] [--edit|-e] [--version|-v] [--exp] [--silence|-s] COMMAND *ARGS"
    puts "ria [--riafile PATH] --json  # 実行せず一覧情報を JSON で取得"
    puts "ria --riafile2cmd [RIAFILE] [NAME]"
    puts "src: " + File.expand_path(__FILE__)
    puts "env: RIA_SILENCE 1 (--silence)"
    puts "env: RIA_CALL 1"
    puts "env: RIA_PWD caller's working directory"
    exit 0
  when "--riafile2cmd"
    raise ArgumentError, "usage: ria --riafile2cmd [RIAFILE] [NAME]" if ARGV.length > 2
    riafile2cmd(ARGV.shift || riafile, ARGV.shift)
    exit 0
  when "--version", "-v"
    puts "ria #{VERSION}"
    exit 0
  when "--edit", "-e"
    system %[start "" "#{File.expand_path(__FILE__).tr("/", "\\")}"]
    exit 0
  when "--dev", "-d"
    system %[start "" "#{File.expand_path("ria.code-workspace", __dir__).tr("/", "\\")}"]
    exit 0
  when "--exp"
    system %[start "" "#{__dir__.tr("/", "\\")}"]
    exit 0
  end

  $riafile = riafile

  unless File.exist?($riafile)
    warn "Riafile not found"
    exit 1
  end

  Dir.chdir(File.dirname($riafile))
  $source_lines = File.readlines($riafile, encoding: "UTF-8")
  if json
    # 定義時の puts / 外部コマンド出力も診断へ。stdout は JSON だけにする。
    output = $stdout.dup
    begin
      $stdout.reopen($stderr)
      eval($source_lines.join, TOPLEVEL_BINDING, $riafile)
    ensure
      $stdout.reopen(output)
      output.close
    end
    require "json"
    puts JSON.generate($order.map(&:describe))
    exit 0
  end
  eval($source_lines.join, TOPLEVEL_BINDING, $riafile)

  # Riafile 定義コマンド一覧の表示
  if key.nil?
    print_cmd_list($order, show_subcommand_parents: true)
    exit
  end

  if key =~ /\A\d+\z/
    key = $order[key.to_i - 1]&.name
  end

  command = $commands[key]

  unless command
    # サブコマンドヘルプ: "ria wt" -> "wt-*" を列挙
    prefix = "#{key}-"
    matches = $order.select { |item| item.name.start_with?(prefix) }
    if matches.any?
      print_cmd_list(matches, title: "ria #{key} : subcommands")
      exit 0
    end

    warn "unknown command: #{key}"
    exit 1
  end

  command.run(ARGV)
  rescue SyntaxError, ArgumentError => e
    warn e.message
    exit 1
  rescue Interrupt
    # Ctrl+C はユーザーによる中断なので、Ruby のバックトレースを表示しない。
    exit 130
  end
end
